import re

def parse(lines):
    stat = re.compile(r'^(?P<k>[A-Za-z][A-Za-z ]*?):\s*(?P<p>[\d.]+%) of (?P<n>\d+)\s*$')
    title = re.compile(r"^(?P<t>Function|File) '(?P<name>.*)'\s*$")
    creating = re.compile(r"^Creating '(?P<f>.*)'\s*$")
    nothing = re.compile(r'^No (?P<w>[A-Za-z][A-Za-z ]*?)\s*$')
    groups = {'Function': [], 'File': []}
    idx = {'Function': [], 'File': []}
    summ = {}
    sidx = []
    cur = None
    curt = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            cur = None
            continue
        m = title.match(s)
        if m:
            curt = m.group('t')
            cur = {curt: m.group('name')}
            groups[curt].append(cur)
            idx[curt].append(i)
            continue
        tgt = cur if cur is not None else summ
        tl = idx[curt] if cur is not None else sidx
        m = stat.match(s)
        if m:
            tgt[m.group('k')] = m.group('p')
            tgt[m.group('k') + ' of'] = int(m.group('n'))
            tl.append(i)
            continue
        m = creating.match(s)
        if m:
            tgt['Creating'] = m.group('f')
            tl.append(i)
            continue
        m = nothing.match(s)
        if m:
            w = m.group('w')
            key = w[:1].upper() + w[1:] + ' executed'
            tgt[key] = 'none'
            tl.append(i)
            continue
    blocks = []
    for t, name in (('Function', 'functions'), ('File', 'files')):
        rows = groups[t]
        if not rows:
            continue
        keys = []
        for r in rows:
            for k in r:
                if k not in keys:
                    keys.append(k)
        recs = [dict((k, r.get(k, '')) for k in keys) for r in rows]
        blocks.append({'name': name, 'kind': 'table', 'lines': idx[t], 'records': recs})
    if summ:
        blocks.append({'name': 'summary', 'kind': 'kv', 'lines': sidx, 'records': [summ]})
    return {'blocks': blocks, 'skip': []}
